package com.nigson.integration.provider;

import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.spec.PKCS8EncodedKeySpec;import java.time.*;import java.util.*;
import com.nigson.shared.events.EventCodec;import com.nigson.shared.problem.Problem;

/** Short-lived Google OAuth service-account assertion exchange; credentials never enter logs. */
public final class GoogleServiceAccountTokenProvider {
 private static final String SCOPE="https://www.googleapis.com/auth/spreadsheets";
 private final URI tokenEndpoint;private final String account;private final PrivateKey key;private final Clock clock;private final HttpClient http;private String cached;private Instant expires=Instant.EPOCH;
 public GoogleServiceAccountTokenProvider(String env,String endpoint,String account,String pkcs8Base64,Clock clock){this.clock=Objects.requireNonNull(clock);if(!Set.of("local","test","dev","qa","stage","prod").contains(env)||account==null||!account.matches("[A-Za-z0-9._+-]{1,128}@[A-Za-z0-9.-]{1,253}")||pkcs8Base64==null||pkcs8Base64.length()>16384)throw new IllegalArgumentException("GOOGLE_SHEETS_CREDENTIALS_REQUIRED");tokenEndpoint=URI.create(endpoint);if(Set.of("local","test").contains(env)){if(!"http".equals(tokenEndpoint.getScheme())||!Set.of("127.0.0.1","localhost").contains(tokenEndpoint.getHost()))throw new IllegalArgumentException("LOCAL_OAUTH_MOCK_REQUIRED");}else if(!"https".equals(tokenEndpoint.getScheme())||!"oauth2.googleapis.com".equals(tokenEndpoint.getHost())||tokenEndpoint.getPort()!=-1||!"/token".equals(tokenEndpoint.getPath()))throw new IllegalArgumentException("GOOGLE_OAUTH_ENDPOINT_REQUIRED");try{byte[] der=Base64.getDecoder().decode(pkcs8Base64);if(der.length<256||der.length>8192)throw new IllegalArgumentException();key=KeyFactory.getInstance("RSA").generatePrivate(new PKCS8EncodedKeySpec(der));}catch(Exception invalid){throw new IllegalArgumentException("GOOGLE_PRIVATE_KEY_INVALID");}this.account=account;http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).followRedirects(HttpClient.Redirect.NEVER).build();}
 public synchronized String token(){if(cached!=null&&expires.isAfter(clock.instant().plusSeconds(60)))return cached;if(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("PROVIDER_CALL_INSIDE_TRANSACTION");try{long now=clock.instant().getEpochSecond();String header=enc(EventCodec.JSON.writeValueAsBytes(Map.of("alg","RS256","typ","JWT")));String claims=enc(EventCodec.JSON.writeValueAsBytes(Map.of("iss",account,"scope",SCOPE,"aud",tokenEndpoint.toString(),"iat",now,"exp",now+3600)));String unsigned=header+"."+claims;Signature signer=Signature.getInstance("SHA256withRSA");signer.initSign(key);signer.update(unsigned.getBytes(StandardCharsets.US_ASCII));String assertion=unsigned+"."+Base64.getUrlEncoder().withoutPadding().encodeToString(signer.sign());String form="grant_type="+URLEncoder.encode("urn:ietf:params:oauth:grant-type:jwt-bearer",StandardCharsets.UTF_8)+"&assertion="+URLEncoder.encode(assertion,StandardCharsets.UTF_8);var request=HttpRequest.newBuilder(tokenEndpoint).timeout(Duration.ofSeconds(5)).header("Content-Type","application/x-www-form-urlencoded").header("Accept","application/json").POST(HttpRequest.BodyPublishers.ofString(form)).build();var response=http.send(request,HttpResponse.BodyHandlers.ofByteArray());if(response.statusCode()!=200||response.body().length>8192||response.headers().allValues("Content-Type").size()!=1||!response.headers().firstValue("Content-Type").orElse("").split(";",2)[0].strip().equals("application/json"))throw new IllegalStateException();var json=EventCodec.JSON.readTree(response.body());if(!json.isObject()||!json.path("access_token").isString()||!json.path("access_token").asString().matches("[A-Za-z0-9._~-]{16,4096}")||!"Bearer".equals(json.path("token_type").asString())||!json.path("expires_in").isIntegralNumber()||json.path("expires_in").asInt()<120||json.path("expires_in").asInt()>3600)throw new IllegalStateException();cached=json.path("access_token").asString();expires=clock.instant().plusSeconds(json.path("expires_in").asInt());return cached;}catch(Exception unavailable){if(unavailable instanceof InterruptedException)Thread.currentThread().interrupt();throw new Problem.Failure(com.nigson.shared.problem.ProblemCode.PROVIDER_UNAVAILABLE);}}
 private static String enc(byte[] value){return Base64.getUrlEncoder().withoutPadding().encodeToString(value);}
 @Override public String toString(){return "GoogleServiceAccountTokenProvider[protected]";}
}
